import type { ImageKey } from './types';

/**
 * Registry of optimized images generated by `npm run assets` from legacy/assets/images.
 * Key = folder/basename (same names as the legacy files), e.g. `portfoilo-website/image copy 2`.
 * Each key has a full-size WebP and a `-480` thumbnail.
 */
const files = import.meta.glob<string>('../assets/images/**/*.webp', {
  eager: true,
  query: '?url',
  import: 'default',
});

const registry = new Map<string, { full: string; thumb: string }>();

for (const [path, url] of Object.entries(files)) {
  const key = path.replace('../assets/images/', '').replace(/\.webp$/, '');
  if (key.endsWith('-480')) continue;
  const thumb = files[path.replace(/\.webp$/, '-480.webp')] ?? url;
  registry.set(key, { full: url, thumb });
}

export function image(key: ImageKey): { full: string; thumb: string } {
  const entry = registry.get(key);
  if (!entry) throw new Error(`Unknown image key: ${key}`);
  return entry;
}
